-- Manpreet Sirohi portfolio: tables, security rules (RLS), storage and starter data.
-- Run this ONCE in Supabase: SQL Editor -> New query -> paste -> Run.
-- It is safe to run again: nothing is dropped, starter data is added only when a table is empty.

-- 1) Who is the admin? Only this email can add, change or delete things.
create or replace function public.is_admin()
returns boolean
language sql stable
as $$
  select coalesce((auth.jwt() ->> 'email') = 'manpreetsirohi26@gmail.com', false);
$$;

-- 2) Tables (created only if missing; existing data is kept)
create table if not exists public.projects (
  id          bigint generated always as identity primary key,
  title       text not null check (char_length(title) between 1 and 120),
  description text not null default '' check (char_length(description) <= 500),
  link        text check (link is null or link = '' or link ~* '^https?://'),
  tags        text[] not null default '{}',
  cover_url   text,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now()
);

alter table public.projects add column if not exists link        text;
alter table public.projects add column if not exists tags        text[] not null default '{}';
alter table public.projects add column if not exists cover_url   text;

create table if not exists public.tools (
  id          bigint generated always as identity primary key,
  name        text not null check (char_length(name) between 1 and 60),
  icon_url    text,
  icon_svg    text check (icon_svg is null or char_length(icon_svg) <= 20000),
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now()
);

create table if not exists public.messages (
  id          bigint generated always as identity primary key,
  name        text not null check (char_length(name) between 1 and 100),
  email       text not null check (char_length(email) between 5 and 200 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  message     text not null check (char_length(message) between 1 and 2000),
  created_at  timestamptz not null default now()
);

-- Editable page text (hero / about / contact)
create table if not exists public.site_content (
  section text not null,
  field_key text not null,
  field_value text,
  updated_at timestamptz not null default now(),
  primary key (section, field_key)
);

-- 3) Row Level Security (the guard). Turn it ON for every table.
alter table public.projects enable row level security;
alter table public.tools    enable row level security;
alter table public.messages enable row level security;
alter table public.site_content enable row level security;

-- projects and tools: everybody can read, only the admin can change
drop policy if exists "projects read"   on public.projects;
drop policy if exists "projects insert" on public.projects;
drop policy if exists "projects update" on public.projects;
drop policy if exists "projects delete" on public.projects;
create policy "projects read"   on public.projects for select to anon, authenticated using (true);
create policy "projects insert" on public.projects for insert to authenticated with check (public.is_admin());
create policy "projects update" on public.projects for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "projects delete" on public.projects for delete to authenticated using (public.is_admin());

drop policy if exists "tools read"   on public.tools;
drop policy if exists "tools insert" on public.tools;
drop policy if exists "tools update" on public.tools;
drop policy if exists "tools delete" on public.tools;
create policy "tools read"   on public.tools for select to anon, authenticated using (true);
create policy "tools insert" on public.tools for insert to authenticated with check (public.is_admin());
create policy "tools update" on public.tools for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "tools delete" on public.tools for delete to authenticated using (public.is_admin());

-- messages: visitors can only SEND, only the admin can read or delete
drop policy if exists "messages send"   on public.messages;
drop policy if exists "messages read"   on public.messages;
drop policy if exists "messages delete" on public.messages;
create policy "messages send"   on public.messages for insert to anon, authenticated with check (true);
create policy "messages read"   on public.messages for select to authenticated using (public.is_admin());
create policy "messages delete" on public.messages for delete to authenticated using (public.is_admin());

-- site_content: everybody can read, only the admin can write
drop policy if exists "content read" on public.site_content;
drop policy if exists "content write" on public.site_content;
create policy "content read" on public.site_content for select to anon, authenticated using (true);
create policy "content write" on public.site_content for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- 4) Storage bucket for cover images and icons (public read, only images up to 2 MB)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('covers', 'covers', true, 2097152, array['image/jpeg','image/png','image/webp','image/gif'])
on conflict (id) do update set public = true, file_size_limit = 2097152,
  allowed_mime_types = array['image/jpeg','image/png','image/webp','image/gif'];

drop policy if exists "covers read"   on storage.objects;
drop policy if exists "covers insert" on storage.objects;
drop policy if exists "covers update" on storage.objects;
drop policy if exists "covers delete" on storage.objects;
create policy "covers read"   on storage.objects for select to anon, authenticated using (bucket_id = 'covers');
create policy "covers insert" on storage.objects for insert to authenticated with check (bucket_id = 'covers' and public.is_admin());
create policy "covers update" on storage.objects for update to authenticated using (bucket_id = 'covers' and public.is_admin()) with check (bucket_id = 'covers' and public.is_admin());
create policy "covers delete" on storage.objects for delete to authenticated using (bucket_id = 'covers' and public.is_admin());

-- 5) Permissions for the website (anon) and the admin (authenticated)
grant usage on schema public to anon, authenticated, service_role;
grant select on public.projects, public.tools, public.messages, public.site_content to anon;
grant insert, select, update, delete on public.projects, public.tools, public.site_content to authenticated;
grant select, insert on public.messages to anon;
grant select, delete on public.messages to authenticated;
grant all on public.projects, public.tools, public.messages, public.site_content to service_role;

-- 6) Starter data (only if the table is empty)
insert into public.projects (title, description, link, tags, cover_url, sort_order)
select * from (values
('Sydney Immigration India website','A multi-page React website for the Kaithal branch, built with OpenCode.','https://sydney-immigration.vercel.app',array['React','OpenCode','Web design'],'sydney-immigration.jpg',1),
('Zero Kata tic-tac-toe','A tic-tac-toe game that anyone can play in the browser.','https://zero-kata-tic-tac-toe.ai.studio',array['Game','AI Studio'],'zero-kata.jpg',2),
('StudyMate AI','An AI study buddy app that helps students study with the help of AI.','https://studymate-ai-ai-study-buddy.ai.studio',array['AI','Study app','AI Studio'],'studymate-ai.jpg',3)
) as v(title, description, link, tags, cover_url, sort_order) where not exists (select 1 from public.projects);

