insert into public.site_content (section, field_key, field_value) values
('hero','name','Manpreet'),
('hero','role','Digital marketer'),
('hero','tagline','Turning ideas into impactful digital experiences.'),
('hero','intro','Hi, I’m Manpreet Sirohi, a digital marketer from Kaithal, Haryana. I plan and create social media content, write scripts and SEO titles for YouTube videos, and use AI tools to build chatbots and websites for businesses.'),
('about','about_title','About me'),
('about','about_text_1','I’m a digital marketer who loves turning ideas into content people actually enjoy. I’m currently learning Digital Marketing with AI at Zed-King and studying BCA.'),
('about','about_text_2','I create content, from Instagram posts to YouTube videos, and I use AI tools to build chatbots, websites and scripts. I’m always eager to learn, adapt and grow.'),
('contact','contact_title','Let’s work together'),
('contact','contact_text','I’m open to new projects and collaborations. Let’s create something that gets real results.'),
('contact','cta_text','Message on Instagram') on conflict (section, field_key) do update set field_value = excluded.field_value, updated_at = now();
